package org.lucenerust.opensearch.neural.util;

import org.opensearch.Version;
import org.opensearch.cluster.metadata.IndexMetadata;
import org.opensearch.cluster.metadata.IndexNameExpressionResolver;
import org.opensearch.cluster.metadata.MappingMetadata;
import org.opensearch.cluster.service.ClusterService;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Class abstracts information related to underlying OpenSearch cluster
 */
public class NeuralSearchClusterUtil {
    @java.lang.SuppressWarnings("all")
    private static final org.apache.logging.log4j.Logger log = org.apache.logging.log4j.LogManager.getLogger(NeuralSearchClusterUtil.class);
    private ClusterService clusterService;
    private IndexNameExpressionResolver indexNameExpressionResolver;
    private static NeuralSearchClusterUtil instance;

    /**
     * Return instance of the cluster context, must be initialized first for proper usage
     * @return instance of cluster context
     */
    public static NeuralSearchClusterUtil instance() {
        if (instance == null) {
            synchronized (NeuralSearchClusterUtil.class) {
                if (instance == null) {
                    instance = new NeuralSearchClusterUtil();
                }
            }
        }
        return instance;
    }

    /**
     * Initializes instance of cluster context by injecting dependencies
     * @param clusterService
     */
    public void initialize(final ClusterService clusterService, final IndexNameExpressionResolver indexNameExpressionResolver) {
        this.clusterService = clusterService;
        this.indexNameExpressionResolver = indexNameExpressionResolver;
    }

    /**
     * Return minimal OpenSearch version based on all nodes currently discoverable in the cluster
     * @return minimal installed OpenSearch version, default to Version.CURRENT which is typically the latest version
     */
    public Version getClusterMinVersion() {
        return this.clusterService.state().getNodes().getMinNodeVersion();
    }

    /**
     * Mapping source of every index in the cluster state, for stats derived from field mappings.
     *
     * An index whose mapping is absent or unparseable is skipped rather than failing the caller: a
     * stats call should still report what the rest of the cluster looks like.
     *
     * @return one mapping map per index, with the type level already stripped
     */
    public List<Map<String, Object>> getAllIndexMappings() {
        List<Map<String, Object>> mappings = new ArrayList<>();
        for (Map.Entry<String, IndexMetadata> entry : clusterService.state().metadata().indices().entrySet()) {
            MappingMetadata mappingMetadata = entry.getValue().mapping();
            if (mappingMetadata == null) {
                continue;
            }
            try {
                mappings.add(mappingMetadata.sourceAsMap());
            } catch (Exception e) {
                log.warn("Failed to parse mapping of index [{}] for stats", entry.getKey(), e);
            }
        }
        return mappings;
    }

    @java.lang.SuppressWarnings("all")
    private NeuralSearchClusterUtil() {
    }
}
